import java.util.*;class RiverRibbonTest{public static void main(String[]a){var global=new EnvironmentMap(EnvironmentMap.filled(2048*2048,92));global.water=EnvironmentMap.filled(2048*2048,62);global.river=new float[2048*2048];List<RiverRibbon.Point> points=new ArrayList<>();for(int x=0;x<=700;x+=10)points.add(new RiverRibbon.Point(530+x,650+45*Math.sin(x/100.),6+2*Math.sin(x/140.),90));global.ribbons=new RiverRibbon.Network(List.of()).append(points,4,2024);var w=new TerraForge.World(512,62,2024);Arrays.fill(w.height,92);var e=w.environment;e.water=EnvironmentMap.filled(512*512,62);e.river=new float[512*512];e.material=new byte[512*512];e.snow=new float[512*512];RiverRibbon.refine(global,w,512,512,62);Set<Integer> residues=new HashSet<>();int wet=0;for(int x=30;x<490;x++){for(int z=0;z<512;z++)if(e.waterY(z*512+x,62)>w.h(x,z)){residues.add(z%8);wet++;break;}}if(residues.size()<7||wet<400)throw new AssertionError("River still follows coarse 8-block mask: "+residues+" wet="+wet);for(int i=0;i<e.height.length;i++)if(e.river[i]>.1&&e.waterY(i,62)<=Math.round(e.height[i]))throw new AssertionError("Dry channel");global.lakeMask=new byte[2048*2048];Arrays.fill(global.lakeMask,(byte)1);float[] old=w.height.clone(),oldWater=e.water.clone();RiverRibbon.refine(global,w,512,512,62);if(!Arrays.equals(old,w.height)||!Arrays.equals(oldWater,e.water))throw new AssertionError("Lake modified");var mapped=global.ribbons.remap(1.1,2,62);double expected=62+(90-62)*1.1+2;if(Math.abs(mapped.segments.get(0).a().water()-expected)>.01)throw new AssertionError("Remapped river level");if(global.share(global.height).ribbons!=global.ribbons)throw new AssertionError("Curve geometry lost through node");System.out.println("PASS: continuous full-resolution curved banks, no coarse-grid snapping, wet channels, lake preservation, water remap and geometry propagation");}}
